from typing import Callable, List

def dep_weight(V: List[object], D: Callable[[object, object], bool], a: object) -> int:
    """Gravitational weight of a: number of theorems depending on a."""
    return sum(1 for b in V if D(a, b))

def in_degree(V: List[object], D: Callable[[object, object], bool], b: object) -> int:
    """In-degree of b: number of theorems b directly depends on."""
    return sum(1 for a in V if D(a, b))

def verify_handshake(n: int) -> None:
    """Verify sum of weights = sum of in-degrees on the linear library of size n."""
    V: List[int] = list(range(n))
    D: Callable[[int, int], bool] = lambda i, j: i < j
    total_w = sum(dep_weight(V, D, a) for a in V)
    total_d = sum(in_degree(V, D, b) for b in V)
    print(f"n={n}: sum w(a)={total_w}, sum d(b)={total_d}, edges={n*(n-1)//2}")
    assert total_w == total_d == n * (n - 1) // 2

if __name__ == "__main__":
    for n in (3, 5, 10):
        verify_handshake(n)

from typing import Callable, List, Tuple

def dep_weight(V: List[object], D: Callable[[object, object], bool], a: object) -> int:
    return sum(1 for b in V if D(a, b))

def grid_bottom_weight(n: int, m: int) -> int:
    """Weight of a bottom-row node in the n x m grid library; should be (n-1)*m."""
    V: List[Tuple[int, int]] = [(r, c) for r in range(n) for c in range(m)]
    D: Callable[[Tuple[int, int], Tuple[int, int]], bool] = lambda p, q: p[0] < q[0]
    w = dep_weight(V, D, (0, 0))
    assert w == (n - 1) * m
    return w

if __name__ == "__main__":
    for (n, m) in ((3, 4), (5, 5), (10, 10)):
        w = grid_bottom_weight(n, m)
        print(f"grid {n}x{m}: bottom-row weight = {w} = (n-1)*m, proof length 1")

