function FIND_ANTI_GRAVITY(V, D, plen, w0, l0):
    S <- { a in V : plen(a) <= l0 }
    return { a in S : DEP_WEIGHT(V, D, a) >= w0 }

function GUARANTEED_THRESHOLD(V, D, plen, l0):
    S <- { a in V : plen(a) <= l0 }
    if S empty: return 0
    return floor( (sum_{a in S} DEP_WEIGHT(V, D, a)) / |S| )

function TRANSITIVE_CLOSURE(V, D):
    reach <- { (a,b) : D(a,b) }
    repeat until no change:
        for a, b, c in V:
            if (a,b) in reach and (b,c) in reach:
                add (a,c) to reach
    return reach

function CLOSURE_WEIGHT(V, D, a):
    reach <- TRANSITIVE_CLOSURE(V, D)
    return |{ b in V : (a,b) in reach }|

